    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("a")).toBe(false); // already gone
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 5)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties all lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);

      // Mutating snapshot must not affect the cart
      snap[0]!.quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(350),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(800),
      };

      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(productA, 5); // subtotal = 5000

      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(5000);
      expect(totals.discountCents).toBe(500);
      // Tax should be computed on discounted subtotal (5000 - 500 = 4500)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
      expect(totals.taxCents).toBe(350);
      // Shipping computed against lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        4500,
      );
      expect(totals.shippingCents).toBe(800);
      // Total = discountedSubtotal + tax + shipping = 4500 + 350 + 800
      expect(totals.totalCents).toBe(5650);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal = 1000
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1); // subtotal = 1000
      expect(cart.totals().discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negativeTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: negativeTax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: negShipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses default policies when no config provided", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const totals = cart.totals();
      // Default: no discount, no tax, free shipping
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout", () => {
  describe("price refresh", () => {
    it("updates prices from priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // Prices refreshed to 1500; subtotal = 2 * 1500 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory checking", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "A is out" })
          .mockResolvedValueOnce({ available: false, reason: "B is out" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        // First denial wins (product "a" was added first)
        expect((err as InventoryError).productId).toBe("a");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US-NY" });
      cart.add(productA, 5); // subtotal = 5000

      const result = await cart.checkout({ asyncTaxProvider });
      // 10% of 5000 = 500
      expect(result.totals.taxCents).toBe(500);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-NY");
    });

    it("propagates async tax provider failure", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi
          .fn()
          .mockRejectedValue(new Error("tax service unavailable")),
      };
      const cart = new Cart();
      cart.add(productA, 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service unavailable",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const discount = new PercentageDiscountPolicy(10);
      const shipping = new FlatShippingCalculator(500);

      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(productA, 2); // original price: 1000 each
      cart.add(productB, 1); // original price: 2000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockImplementation((id: string) =>
            Promise.resolve(id === "a" ? 1200 : 2500),
          ),
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed prices: a=1200*2=2400, b=2500*1=2500 → subtotal=4900
      expect(result.totals.subtotalCents).toBe(4900);
      // Discount: 10% of 4900 = 490
      expect(result.totals.discountCents).toBe(490);
      // discountedSubtotal = 4900 - 490 = 4410
      // Tax: 8% of 4410 = 352.8 → 352
      expect(result.totals.taxCents).toBe(352);
      // Shipping: flat 500
      expect(result.totals.shippingCents).toBe(500);
      // Total = 4410 + 352 + 500 = 5262
      expect(result.totals.totalCents).toBe(5262);
    });

    it("works with no collaborators (uses sync defaults)", async () => {
      const cart = new Cart();
      cart.add(productA, 3); // subtotal = 3000
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.totalCents).toBe(3000);
    });

    it("returns refreshed lines in the result", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(7777),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(7777);
      expect(result.lines[0]!.product.id).toBe("a");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [10000, 0],
    [0, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      // 15% of 999 = 149.85 → 149
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, plus 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });

    it("clamps negative child results to 0", () => {
      const negativeMock = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // max(0, -100) + 300 = 300
      expect(composite.computeDiscountCents(5000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000, remaining = 9000
      // Second: 10% of 9000 = 900, remaining = 8100
      // Total discount = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters: larger discount first yields different result", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      const composite2 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // c1: 50% of 1000 = 500, then min(100, 500) = 100 → total 600
      // c2: min(100, 1000) = 100, remaining 900, 50% of 900 = 450 → total 550
      expect(composite1.computeDiscountCents(1000)).toBe(600);
      expect(composite2.computeDiscountCents(1000)).toBe(550);
    });

    it("chain stops early when remaining hits zero", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(5000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed: min(5000, 1000) = 1000, remaining = 0
      // Percentage on 0 = 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative child results to 0", () => {
      const negativeMock = { computeDiscountCents: () => -500 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -500) = 0, remaining = 5000
      // min(200, 5000) = 200
      // Total = 200
      expect(composite.computeDiscountCents(5000)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(5000)).toBe(300);
  });
});

