import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product with the given quantity", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(3);
    });

    it("merges quantities when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("tracks distinct products separately", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      const badProduct: Product = {
        id: "bad",
        name: "Bad",
        unitPriceCents: -100,
      };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 5);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("a")).toBe(false); // already gone
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 5)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties all lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);

      // Mutating snapshot must not affect the cart
      snap[0]!.quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(350),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(800),
      };

      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(productA, 5); // subtotal = 5000

      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(5000);
      expect(totals.discountCents).toBe(500);
      // Tax should be computed on discounted subtotal (5000 - 500 = 4500)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
      expect(totals.taxCents).toBe(350);
      // Shipping computed against lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        4500,
      );
      expect(totals.shippingCents).toBe(800);
      // Total = discountedSubtotal + tax + shipping = 4500 + 350 + 800
      expect(totals.totalCents).toBe(5650);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal = 1000
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1); // subtotal = 1000
      expect(cart.totals().discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negativeTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: negativeTax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: negShipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("uses default policies when no config provided", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const totals = cart.totals();
      // Default: no discount, no tax, free shipping
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout", () => {
  describe("price refresh", () => {
    it("updates prices from priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // Prices refreshed to 1500; subtotal = 2 * 1500 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("inventory checking", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "A is out" })
          .mockResolvedValueOnce({ available: false, reason: "B is out" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        // First denial wins (product "a" was added first)
        expect((err as InventoryError).productId).toBe("a");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US-NY" });
      cart.add(productA, 5); // subtotal = 5000

      const result = await cart.checkout({ asyncTaxProvider });
      // 10% of 5000 = 500
      expect(result.totals.taxCents).toBe(500);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-NY");
    });

    it("propagates async tax provider failure", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi
          .fn()
          .mockRejectedValue(new Error("tax service unavailable")),
      };
      const cart = new Cart();
      cart.add(productA, 1);

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service unavailable",
      );
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh + inventory + async tax + discount + shipping", async () => {
      const discount = new PercentageDiscountPolicy(10);
      const shipping = new FlatShippingCalculator(500);

      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(productA, 2); // original price: 1000 each
