import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("always returns 0", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate < 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects out-of-range region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "FR": -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "FR": 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to defaultRate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-100, "US-CA")).toBe(0);
    });

    it("defaults to 0 when no defaultRate provided and region is unknown", () => {
      const calc2 = new RegionalTaxCalculator({ "US": 0.1 });
      expect(calc2.computeTaxCents(10000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using provided rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    const result = await calc.computeTaxCents(10000, "US");
    expect(result).toBe(1000);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("returns 0 for zero taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable amount", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network failure")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(
      "network failure",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across all lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

